"use client";

import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import { ArrowRight, Check, ChevronRight, Clock3, Copy, ExternalLink, Link2, MapPin, Minus, Plus, Search, Trash2, UploadCloud } from "lucide-react";
import { apiFetch } from "@/lib/api";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { cn } from "@/lib/utils";

const columns = [
  "inquiry", "awaiting_confirmation", "confirmed", "queued", "preparing", "frying", "packed",
  "ready_for_pickup", "ready_for_booking", "booked", "completed", "cancelled"
] as const;
const statusOptions = [
  "inquiry", "awaiting_confirmation", "confirmed", "queued", "preparing", "frying", "packed",
  "ready_for_pickup", "ready_for_booking", "booked", "completed", "cancelled"
] as const;
const deliveryOptions = ["pickup", "maxim", "own_delivery"] as const;
const deliveryMethodLabels: Record<string, string> = { pickup: "Pickup", maxim: "Maxim", own_delivery: "Own Rider" };
const deliverySelectOptions = deliveryOptions.map((option) => ({ label: deliveryMethodLabels[option] ?? option, value: option }));
const paymentOptions = ["cod", "gcash"] as const;
const paymentSelectOptions = paymentOptions.map((option) => ({ label: option === "cod" ? "COD" : "GCash", value: option }));
const statusSelectOptions = statusOptions.map((status) => ({ label: status.replaceAll("_", " ").replace(/\b\w/g, (char) => char.toUpperCase()), value: status }));
const statusFilterOptions = [{ label: "All Statuses", value: "all" }, ...statusSelectOptions];

type ProductCatalogItem = { name: string; price: number; available: boolean; sortOrder?: number };
type ProductOption = { label: string; value: string; price: number; available: boolean };
type OrderNoteView = { id: string; body: string; createdAt?: string | null };
type OrderLineItemView = { name: string; quantity: number; price?: number; subtotal?: number };
type EditableOrderLineItem = { productName: string; quantity: string; price: number };

const statusTone: Record<string, string> = {
  inquiry: "bg-white/[0.08] text-foreground/75", awaiting_confirmation: "bg-amber-500/15 text-amber-200", confirmed: "bg-sky-500/15 text-sky-200",
  queued: "bg-violet-500/15 text-violet-200", preparing: "bg-fuchsia-500/15 text-fuchsia-200", frying: "bg-orange-500/15 text-orange-200",
  packed: "bg-cyan-500/15 text-cyan-200", ready_for_pickup: "bg-teal-500/15 text-teal-200", ready_for_booking: "bg-lime-500/15 text-lime-200",
  booked: "bg-emerald-500/15 text-emerald-200", completed: "bg-green-500/15 text-green-200", cancelled: "bg-rose-500/15 text-rose-200"
};
const statusDot: Record<string, string> = {
  inquiry: "bg-white/40", awaiting_confirmation: "bg-amber-400", confirmed: "bg-sky-400", queued: "bg-violet-400", preparing: "bg-fuchsia-400",
  frying: "bg-orange-400", packed: "bg-cyan-400", ready_for_pickup: "bg-teal-400", ready_for_booking: "bg-lime-400", booked: "bg-emerald-400",
  completed: "bg-green-400", cancelled: "bg-rose-400"
};
const deliveryBadgeTone: Record<string, string> = { pickup: "bg-white/[0.08] text-foreground/70", maxim: "bg-sky-500/18 text-sky-200", own_delivery: "bg-violet-500/18 text-violet-200" };
const scheduleFormatter = new Intl.DateTimeFormat("en-US", { timeZone: "Asia/Manila", year: "numeric", month: "numeric", day: "numeric", hour: "numeric", minute: "2-digit" });
const noteTimeFormatter = new Intl.DateTimeFormat("en-US", { timeZone: "Asia/Manila", month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });

export function OrdersBoard({ orders }: { orders: Array<any> }) {
  const [items, setItems] = useState(orders);
  const [selectedId, setSelectedId] = useState<string | null>(orders[0]?.id ?? null);
  const [selectedStatus, setSelectedStatus] = useState<string>(orders[0]?.status ?? "queued");
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [selectedDate, setSelectedDate] = useState(getTodayDateInputValue);
  const [isDateChanging, setIsDateChanging] = useState(false);
  const [statusFilter, setStatusFilter] = useState("all");
  const [editMode, setEditMode] = useState(false);
  const [copiedDetails, setCopiedDetails] = useState(false);
  const [copiedTracking, setCopiedTracking] = useState(false);
  const [copiedNotes, setCopiedNotes] = useState(false);
  const [noteDraft, setNoteDraft] = useState("");
  const [detailOpen, setDetailOpen] = useState(false);
  const [pending, startTransition] = useTransition();
  const [deletePending, startDeleteTransition] = useTransition();
  const [exportPending, startExportTransition] = useTransition();
  const [exportResult, setExportResult] = useState<{ name: string; webViewLink?: string } | null>(null);
  const lastSelectedOrderIdRef = useRef<string | null>(null);
  const latestRefreshIdRef = useRef(0);
  const selectedDateRef = useRef(selectedDate);
  const searchRef = useRef(search);
  const [form, setForm] = useState({
    customerName: "", phoneNumber: "", deliveryFee: "0", discountAmount: "0", deliveryMethod: "pickup", paymentMethod: "cod", location: "", address: "",
    preferredSchedule: "", maximStatus: "booked", maximScheduledAt: "", maximEta: "", maximTrackingLink: "", maximRiderName: "", maximRiderPlate: "", maximBookingNotes: "", notes: ""
  });
  const [lineItems, setLineItems] = useState<EditableOrderLineItem[]>([]);
  const [catalogProducts, setCatalogProducts] = useState<ProductCatalogItem[]>([]);
  const productOptions = useMemo<ProductOption[]>(() => catalogProducts.slice().sort((a, b) => Number(a.sortOrder ?? 0) - Number(b.sortOrder ?? 0) || a.name.localeCompare(b.name)).map((product) => ({
    label: `${product.name} - Php ${Number(product.price)}${product.available ? "" : " — SOLD OUT"}`,
    value: product.name, price: Number(product.price), available: product.available !== false
  })), [catalogProducts]);

  useEffect(() => {
    let active = true;
    void apiFetch<ProductCatalogItem[]>("/products")
      .then((result) => { if (active) setCatalogProducts(Array.isArray(result) ? result : []); })
      .catch(() => { if (active) setCatalogProducts([]); });
    return () => { active = false; };
  }, []);

  const refreshOrders = useCallback(async (dateValue = selectedDateRef.current, searchValue = searchRef.current) => {
    const refreshId = latestRefreshIdRef.current + 1;
    latestRefreshIdRef.current = refreshId;
    const normalizedSearch = searchValue.trim();
    const queryParams = new URLSearchParams();
    if (dateValue) queryParams.set("date", dateValue);
    if (normalizedSearch) queryParams.set("search", normalizedSearch);
    const query = queryParams.toString() ? `?${queryParams.toString()}` : "";
    const refreshed = await apiFetch<any[]>(`/orders${query}`);
    if (refreshId !== latestRefreshIdRef.current || dateValue !== selectedDateRef.current || searchValue !== searchRef.current) return;
    const nextItems = Array.isArray(refreshed) ? refreshed : [];
    setItems(nextItems);
    setSelectedId((current) => !current ? (nextItems[0]?.id ?? null) : nextItems.some((order) => order.id === current) ? current : (nextItems[0]?.id ?? null));
  }, []);

  useEffect(() => { selectedDateRef.current = selectedDate; }, [selectedDate]);
  useEffect(() => { searchRef.current = search; }, [search]);
  useEffect(() => {
    // The selected date is the source of truth. Parent/realtime orders are only
    // allowed to hydrate the board while viewing today.
    if (search.trim()) return;
    if (selectedDate !== getTodayDateInputValue()) return;
    setItems(orders);
    setSelectedId((current) => current ?? orders[0]?.id ?? null);
  }, [orders, search, selectedDate]);
  useEffect(() => {
    let cancelled = false;
    const searchValue = search;
    const dateValue = selectedDate;
    setIsDateChanging(true);
    setItems([]);
    setSelectedId(null);
    const timeout = window.setTimeout(() => {
      refreshOrders(dateValue, searchValue).catch((err) => { if (!cancelled) setError(err instanceof Error ? err.message : "Unable to refresh orders"); }).finally(() => { if (!cancelled) setIsDateChanging(false); });
    }, searchValue.trim() ? 250 : 0);
    return () => { cancelled = true; window.clearTimeout(timeout); };
  }, [refreshOrders, search, selectedDate]);

  const filteredItems = useMemo(() => {
    const query = search.trim().toLowerCase();
    return items.filter((item) => {
      const matchesSearch = !query || [item.customer?.name, item.customer?.phoneNumber, item.orderNumber, item.deliveryMethod, item.paymentMethod, item.status, item.location, item.address, item.notes, item.delivery?.areaGroup, item.delivery?.riderName, item.delivery?.riderPlate, ...(item.orderNotes ?? []).map((note: any) => note.body)].filter(Boolean).some((value) => String(value).toLowerCase().includes(query));
      return matchesSearch && (statusFilter === "all" || item.status === statusFilter);
    }).sort(compareOrdersBySchedule);
  }, [items, search, statusFilter]);

  const selectedOrder = useMemo(() => filteredItems.find((item) => item.id === selectedId) ?? filteredItems[0] ?? null, [filteredItems, selectedId]);
  useEffect(() => { if (selectedOrder?.id !== selectedId) setSelectedId(selectedOrder?.id ?? null); }, [selectedId, selectedOrder]);

  useEffect(() => {
    if (!selectedOrder) return;
    const isNewSelection = lastSelectedOrderIdRef.current !== selectedOrder.id;
    lastSelectedOrderIdRef.current = selectedOrder.id;
    setSelectedStatus((current) => current === selectedOrder.status ? current : selectedOrder.status);
    if (isNewSelection) {
      setForm({
        customerName: selectedOrder.customer?.name ?? "", phoneNumber: selectedOrder.customer?.phoneNumber ?? "", deliveryFee: String(selectedOrder.deliveryFee ?? 0), discountAmount: String(selectedOrder.discountAmount ?? 0),
        deliveryMethod: selectedOrder.deliveryMethod ?? "pickup", paymentMethod: selectedOrder.paymentMethod ?? "cod", location: selectedOrder.location ?? "", address: selectedOrder.address ?? "",
        preferredSchedule: selectedOrder.preferredSchedule ? toInputDate(selectedOrder.preferredSchedule) : getLocalDateTimeInputValue(),
        maximStatus: ["booked", "completed", "cancelled"].includes(selectedOrder.delivery?.status) ? selectedOrder.delivery.status : "booked",
        maximScheduledAt: selectedOrder.delivery?.scheduledAt ? toInputDate(selectedOrder.delivery.scheduledAt) : getLocalDateTimeInputValue(), maximEta: selectedOrder.delivery?.eta ? toInputDate(selectedOrder.delivery.eta) : "",
        maximTrackingLink: selectedOrder.delivery?.trackingLink ?? "", maximRiderName: selectedOrder.delivery?.riderName ?? "", maximRiderPlate: selectedOrder.delivery?.riderPlate ?? "", maximBookingNotes: selectedOrder.delivery?.bookingNotes ?? "",
        notes: stripItemsBlock(selectedOrder.notes ?? "")
      });
      setLineItems(createEditableLineItems(selectedOrder, productOptions));
      setError(null); setCopiedDetails(false); setCopiedTracking(false); setCopiedNotes(false); setNoteDraft("");
      return;
    }
    if (editMode) return;
    setForm((currentForm) => currentForm.customerName && currentForm.phoneNumber && currentForm.address && currentForm.location ? currentForm : {
      customerName: selectedOrder.customer?.name ?? "", phoneNumber: selectedOrder.customer?.phoneNumber ?? "", deliveryFee: String(selectedOrder.deliveryFee ?? 0), discountAmount: String(selectedOrder.discountAmount ?? 0), deliveryMethod: selectedOrder.deliveryMethod ?? "pickup", paymentMethod: selectedOrder.paymentMethod ?? "cod", location: selectedOrder.location ?? "", address: selectedOrder.address ?? "", preferredSchedule: selectedOrder.preferredSchedule ? toInputDate(selectedOrder.preferredSchedule) : getLocalDateTimeInputValue(), maximStatus: ["booked", "completed", "cancelled"].includes(selectedOrder.delivery?.status) ? selectedOrder.delivery.status : "booked", maximScheduledAt: selectedOrder.delivery?.scheduledAt ? toInputDate(selectedOrder.delivery.scheduledAt) : getLocalDateTimeInputValue(), maximEta: selectedOrder.delivery?.eta ? toInputDate(selectedOrder.delivery.eta) : "", maximTrackingLink: selectedOrder.delivery?.trackingLink ?? "", maximRiderName: selectedOrder.delivery?.riderName ?? "", maximRiderPlate: selectedOrder.delivery?.riderPlate ?? "", maximBookingNotes: selectedOrder.delivery?.bookingNotes ?? "", notes: stripItemsBlock(selectedOrder.notes ?? "")
    });
  }, [editMode, selectedOrder?.id, selectedOrder?.status]);

  useEffect(() => {
    if (!selectedOrder || productOptions.length === 0) return;
    setLineItems((current) => {
      const catalogNames = new Set(productOptions.map((product) => product.value.toLowerCase()));
      const hasAllCatalogProducts = productOptions.every((product) => current.some((item) => item.productName.toLowerCase() === product.value.toLowerCase()));
      return hasAllCatalogProducts ? current : createEditableLineItems(selectedOrder, productOptions);
    });
  }, [productOptions, selectedOrder?.id]);

  const totals = useMemo(() => ({ totalOrders: items.length, visibleOrders: filteredItems.length }), [filteredItems.length, items.length]);
  const visibleColumns = useMemo(() => {
    if (filteredItems.length === 0) return [];
    const active = columns.filter((status) => filteredItems.some((item) => item.status === status) || selectedOrder?.status === status);
    return active.length > 0 ? active : ["queued", "ready_for_booking", "booked"];
  }, [filteredItems, selectedOrder]);
  const countLabel = useMemo(() => search.trim() || statusFilter !== "all" || selectedDate ? `${totals.visibleOrders} of ${totals.totalOrders}` : `${totals.totalOrders} orders`, [search, selectedDate, statusFilter, totals.totalOrders, totals.visibleOrders]);
  const queuedFlavorTotals = useMemo(() => {
    const totalsByFlavor = new Map<string, number>();
    filteredItems.filter((order) => order.status === "queued").forEach((order) => {
      const lineItems = getOrderLineItems(order);
      const displayItems = lineItems.length > 0 ? lineItems : [{ name: "Empanada", quantity: Number(order.quantity ?? 0) }];
      displayItems.forEach((item) => { const quantity = Number(item.quantity ?? 0); if (item.name && quantity >= 1) totalsByFlavor.set(item.name, (totalsByFlavor.get(item.name) ?? 0) + quantity); });
    });
    return [...totalsByFlavor.entries()].map(([name, quantity]) => ({ name, quantity })).sort((a, b) => b.quantity - a.quantity || a.name.localeCompare(b.name));
  }, [filteredItems]);
  const queuedFlavorQuantity = queuedFlavorTotals.reduce((sum, item) => sum + item.quantity, 0);
  const orderItemSummary = useMemo(() => {
    const items = lineItems.map((item) => { const quantity = Number(item.quantity || 0); return quantity > 0 ? { name: item.productName, quantity, price: item.price, subtotal: quantity * item.price } : null; }).filter((item): item is NonNullable<typeof item> => Boolean(item));
    const quantity = items.reduce((sum, item) => sum + item.quantity, 0); const subtotal = items.reduce((sum, item) => sum + item.subtotal, 0); const deliveryFee = form.deliveryMethod === "pickup" ? 0 : Number(form.deliveryFee || 0); const discountAmount = Number(form.discountAmount || 0);
    return { items, quantity, subtotal, deliveryFee, discountAmount, total: Math.max(0, subtotal + deliveryFee - discountAmount), unitPrice: quantity > 0 ? subtotal / quantity : 0 };
  }, [form.deliveryFee, form.deliveryMethod, form.discountAmount, lineItems]);

  function updateStatus() { if (!selectedOrder) return; setError(null); startTransition(async () => { try { const updated = await apiFetch<any>(`/orders/${selectedOrder.id}/status`, { method: "PATCH", body: JSON.stringify({ status: selectedStatus }) }); setItems((current) => current.map((item) => item.id === updated.id ? updated : item)); } catch (err) { setError(err instanceof Error ? err.message : "Unable to update status"); } }); }
  function saveDetails() {
    if (!selectedOrder) return; setError(null); startTransition(async () => { try { if (orderItemSummary.quantity < 1) { setError("Add at least one item quantity before saving."); return; }
      let updated = await apiFetch<any>(`/orders/${selectedOrder.id}`, { method: "PATCH", body: JSON.stringify({ customerName: form.customerName, phoneNumber: form.phoneNumber || undefined, quantity: orderItemSummary.quantity, unitPrice: orderItemSummary.unitPrice, deliveryFee: orderItemSummary.deliveryFee, discountAmount: orderItemSummary.discountAmount, items: orderItemSummary.items, deliveryMethod: form.deliveryMethod, paymentMethod: form.paymentMethod, location: form.location || undefined, address: form.address || undefined, preferredSchedule: form.preferredSchedule ? new Date(form.preferredSchedule).toISOString() : undefined, notes: form.notes.trim() || undefined }) });
      if (shouldSaveMaximTracking()) updated = await apiFetch<any>(`/deliveries/orders/${selectedOrder.id}`, { method: "PATCH", body: JSON.stringify({ status: form.maximStatus, scheduledAt: form.maximScheduledAt ? new Date(form.maximScheduledAt).toISOString() : undefined, eta: form.maximEta ? new Date(form.maximEta).toISOString() : undefined, trackingLink: form.maximTrackingLink || undefined, riderName: form.maximRiderName || undefined, riderPlate: form.maximRiderPlate || undefined, bookingNotes: form.maximBookingNotes || undefined }) });
      await refreshOrders(); setSelectedId(updated.id); setEditMode(false);
    } catch (err) { setError(err instanceof Error ? err.message : "Unable to save order details"); } });
  }
  function shouldSaveMaximTracking() { return Boolean(selectedOrder?.delivery) || Boolean(form.maximTrackingLink.trim() || form.maximRiderName.trim() || form.maximRiderPlate.trim() || form.maximBookingNotes.trim() || form.maximEta); }
  function shouldShowMaximTrackingFields() { return form.deliveryMethod === "maxim" || selectedStatus === "ready_for_booking" || selectedStatus === "booked" || selectedOrder?.deliveryMethod === "maxim" || Boolean(selectedOrder?.delivery); }
  function updateLineItem(productName: string, quantity: string) { const normalized = quantity === "" ? "" : String(Math.max(0, Number(quantity))); setLineItems((current) => current.map((item) => item.productName === productName ? { ...item, quantity: normalized } : item)); }
  function stepLineItem(productName: string, delta: number) { setLineItems((current) => current.map((item) => { if (item.productName !== productName) return item; const nextQuantity = Math.max(0, Number(item.quantity || 0) + delta); return { ...item, quantity: nextQuantity > 0 ? String(nextQuantity) : "" }; })); }
  function addNote() { if (!selectedOrder) return; setError(null); startTransition(async () => { try { const updated = await apiFetch<any>(`/orders/${selectedOrder.id}/notes`, { method: "POST", body: JSON.stringify({ body: noteDraft }) }); setItems((current) => current.map((item) => item.id === updated.id ? updated : item)); setNoteDraft(""); } catch (err) { setError(err instanceof Error ? err.message : "Unable to add note"); } }); }
  async function copyNotes() { const text = getOrderNotes(selectedOrder).map((note) => note.body).join("\n\n"); if (!text) return; try { await navigator.clipboard.writeText(text); setCopiedNotes(true); window.setTimeout(() => setCopiedNotes(false), 1600); } catch { setCopiedNotes(false); } }
  async function copyOrderDetails() { if (!selectedOrder) return; try { await navigator.clipboard.writeText(formatOrderDetailsForCopy(selectedOrder)); setCopiedDetails(true); window.setTimeout(() => setCopiedDetails(false), 1600); } catch { setCopiedDetails(false); } }
  async function copyTrackingLink() { if (!selectedOrder || typeof window === "undefined") return; try { await navigator.clipboard.writeText(`${window.location.origin}/track/${selectedOrder.id}`); setCopiedTracking(true); window.setTimeout(() => setCopiedTracking(false), 1600); } catch { setCopiedTracking(false); } }
  function exportOrdersToExcel() { setError(null); setExportResult(null); startExportTransition(async () => { try { const result = await apiFetch<{ name: string; webViewLink?: string }>("/orders/export/google-drive", { method: "POST", body: JSON.stringify({ orderIds: filteredItems.map((order) => order.id) }) }); setExportResult(result); } catch (err) { setError(err instanceof Error ? err.message : "Unable to upload export to Google Drive"); } }); }
  function deleteOrder() { if (!selectedOrder) return; const confirmed = window.confirm(`Delete order ${selectedOrder.orderNumber}? This cannot be undone.`); if (!confirmed) return; setError(null); startDeleteTransition(async () => { try { await apiFetch(`/orders/${selectedOrder.id}`, { method: "DELETE" }); setItems((current) => current.filter((item) => item.id !== selectedOrder.id)); setSelectedId((current) => current === selectedOrder.id ? null : current); setDetailOpen(false); } catch (err) { setError(err instanceof Error ? err.message : "Unable to delete order"); } }); }

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-3 lg:flex-row lg:items-end lg:justify-between">
        <div className="min-w-0"><p className="text-[11px] uppercase tracking-[0.24em] text-foreground/35">Operations Board</p><h2 className="mt-1 text-xl font-semibold sm:text-2xl">Order Workflow</h2></div>
        <div className="grid gap-3 sm:grid-cols-2 lg:flex lg:items-center">
          <label className="relative block min-w-0 sm:w-[320px]"><Search size={16} className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-foreground/35" /><Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search by customer, order no., area, phone, or notes" className="pl-10 sm:h-11" /></label>
          <Select value={statusFilter} onChange={setStatusFilter} options={statusFilterOptions} className="sm:w-[220px]" />
          <Input type="date" value={selectedDate} onChange={(e) => { const nextDate = e.target.value; selectedDateRef.current = nextDate; latestRefreshIdRef.current += 1; setSelectedDate(nextDate); setItems([]); setSelectedId(null); setIsDateChanging(true); }} className="w-full sm:h-11 sm:w-[168px]" />
          <Button type="button" variant="ghost" onClick={exportOrdersToExcel} disabled={filteredItems.length === 0 || exportPending} className="h-11 justify-center gap-2 border border-line/80 px-4"><UploadCloud size={16} />{exportPending ? "Uploading..." : "Upload Excel"}</Button>
          <Badge className="justify-center border border-line/70 bg-panel text-foreground/70 sm:justify-start">{isDateChanging ? "Loading..." : countLabel}</Badge>
        </div>
      </div>
      {exportResult ? <div className="rounded-lg border border-line/80 bg-panel/70 px-4 py-3 text-sm text-foreground/70">Uploaded <span className="font-medium text-foreground">{exportResult.name}</span> to Google Drive.{exportResult.webViewLink ? <a className="ml-2 text-accent hover:underline" href={exportResult.webViewLink} target="_blank" rel="noreferrer">Open file</a> : null}</div> : null}
      <Card className="border-line/70 bg-panel/80 p-3 shadow-none"><div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div><p className="text-[10px] uppercase tracking-[0.22em] text-foreground/35">Queued Flavor Count</p><p className="mt-1 text-sm text-foreground/55">{queuedFlavorTotals.length} flavor{queuedFlavorTotals.length === 1 ? "" : "s"} · {queuedFlavorQuantity} pcs total</p></div><div className="flex flex-wrap gap-2">{queuedFlavorTotals.length > 0 ? queuedFlavorTotals.map((item) => <Badge key={item.name} className="border border-line/70 bg-black/15 text-foreground/72">{item.name}: <span className="ml-1 font-semibold text-foreground">{item.quantity} pcs</span></Badge>) : <span className="text-sm text-foreground/45">No queued flavors.</span>}</div></div></Card>
      <div className="min-w-0 overflow-x-auto rounded-lg border border-line/80 bg-panel/55 p-2 pb-3 shadow-sm shadow-black/10 sm:p-3 sm:pb-4"><div className="grid min-w-full grid-flow-col auto-cols-[minmax(224px,85vw)] gap-3 sm:auto-cols-[minmax(248px,1fr)]">{visibleColumns.map((status) => { const columnOrders = filteredItems.filter((item) => item.status === status); const columnQuantity = columnOrders.reduce((sum, order) => sum + Number(order.quantity ?? 0), 0); return <Card key={status} className="min-w-[224px] overflow-hidden border-line/70 bg-panel/90 p-0 shadow-none sm:min-w-[248px]"><div className={cn("h-[3px] w-full", statusDot[status])} /><div className="p-3"><div className="mb-3 flex items-center justify-between border-b border-line/70 pb-3"><div className="min-w-0"><div className="flex items-center gap-1.5"><span className={cn("h-1.5 w-1.5 shrink-0 rounded-full", statusDot[status])} /><p className="text-[10px] uppercase tracking-[0.22em] text-foreground/35">Stage</p></div><h3 className="mt-1 truncate text-[15px] font-semibold capitalize leading-tight">{status.replaceAll("_", " ")}</h3><p className="mt-1 text-xs text-foreground/45">{columnQuantity} pcs total</p></div><Badge className={cn("shrink-0 border-0 tabular-nums", statusTone[status])}>{columnOrders.length}</Badge></div><div className="space-y-2.5">{columnOrders.map((order) => { const orderLineItems = getOrderLineItems(order); const notePreview = getOrderNotePreview(order); return <button key={order.id} type="button" onClick={() => { setSelectedId(order.id); setDetailOpen(true); }} className={cn("w-full rounded-lg border px-3.5 py-3 text-left transition duration-150 ease-out hover:-translate-y-0.5", selectedOrder?.id === order.id ? "border-accent/60 bg-accent/[0.08] shadow-[0_0_0_1px_rgb(var(--accent)/0.18)]" : "border-line/70 bg-black/[0.08] hover:border-accent/35 hover:bg-white/[0.04] hover:shadow-[0_10px_28px_rgba(0,0,0,0.28)]")}><div className="flex items-start justify-between gap-2"><div className="min-w-0"><p className="truncate text-[17px] font-semibold leading-tight">{order.customer?.name}</p><p className="mt-1 text-[11px] uppercase tracking-[0.16em] text-foreground/30">{order.orderNumber}</p></div><Badge className={cn("shrink-0 border-0 text-[11px]", deliveryBadgeTone[order.deliveryMethod] ?? deliveryBadgeTone.pickup)}>{deliveryMethodLabels[order.deliveryMethod] ?? order.deliveryMethod}</Badge></div><OrderItemsList items={orderLineItems} fallbackQuantity={order.quantity} />{notePreview ? <div className="mt-3 rounded-lg border border-line/70 bg-white/[0.03] px-3 py-2.5"><p className="text-[10px] uppercase tracking-[0.16em] text-foreground/28">Note</p><p className="mt-1 line-clamp-3 whitespace-pre-wrap text-sm leading-5 text-foreground/70">{notePreview}</p></div> : null}<div className="mt-3 grid grid-cols-2 gap-2"><CompactStat label="Qty" value={`${order.quantity}`} suffix="pcs" /><CompactStat label="To Pay" value={`Php ${String(order.totalAmount)}`} accent /></div><div className="mt-3 space-y-1.5 text-sm text-foreground/62"><InfoLine icon={MapPin} text={order.location ?? "No area"} /><InfoLine icon={Clock3} text={formatSchedule(order.preferredSchedule)} /></div></button>; })}{columnOrders.length === 0 ? <div className="h-2" /> : null}</div></div></Card>; })}</div>{filteredItems.length === 0 ? <div className="flex min-h-[220px] items-center justify-center px-6 py-10 text-center text-sm text-foreground/45">No orders matched your search.</div> : null}</div>
      {detailOpen ? <div className="fixed inset-0 z-40"><button type="button" aria-label="Close order details" onClick={() => setDetailOpen(false)} className="absolute inset-0 bg-black/55 backdrop-blur-[3px]" /><div className="absolute inset-y-0 right-0 w-full max-w-[480px] p-2 sm:p-4"><Card className="flex h-full flex-col overflow-hidden border-line/90 bg-panel p-0 shadow-[0_24px_80px_rgba(0,0,0,0.55)]">{selectedOrder ? <div className="flex min-h-0 flex-1 flex-col"><div className={cn("h-[3px] w-full shrink-0", statusDot[selectedOrder.status])} /><div className="shrink-0 border-b border-line/75 bg-panel p-4 sm:p-6"><div className="mb-4 flex items-center justify-between"><button type="button" onClick={() => setDetailOpen(false)} className="inline-flex items-center gap-2 rounded-md border border-line/80 px-3 py-1.5 text-xs text-foreground/55 transition hover:border-accent/35 hover:text-foreground"><ChevronRight size={14} />Hide details</button></div><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="text-[11px] uppercase tracking-[0.24em] text-foreground/30">Selected Order</p><h3 className="mt-2 truncate text-2xl font-semibold leading-tight sm:text-[32px] sm:leading-none">{selectedOrder.customer?.name}</h3><p className="mt-2 font-mono text-sm text-foreground/40">{selectedOrder.orderNumber}</p></div><Badge className={cn("shrink-0 border-0", statusTone[selectedOrder.status])}>{selectedOrder.status.replaceAll("_", " ")}</Badge></div></div>
      <div className="min-h-0 flex-1 overflow-y-auto p-4 sm:p-6"><div className="space-y-4"><div className="space-y-2.5 rounded-lg border border-accent/25 bg-accent/[0.05] p-4"><label className="text-sm font-medium text-foreground/72">Update status</label><Select value={selectedStatus} onChange={setSelectedStatus} options={statusSelectOptions} /><Button className="w-full" onClick={updateStatus} disabled={pending || deletePending || selectedStatus === selectedOrder.status}>{pending ? "Updating..." : "Save Status"}</Button>{selectedOrder.status !== selectedStatus ? <p className="flex items-center gap-2 text-xs text-foreground/45"><ArrowRight size={14} />{selectedOrder.status.replaceAll("_", " ")} to {selectedStatus.replaceAll("_", " ")}</p> : null}{error ? <p className="text-sm text-danger">{error}</p> : null}</div>
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><p className="text-sm font-medium text-foreground/68">Order details</p><div className="flex flex-wrap gap-2">{!editMode ? <Button variant="ghost" className="px-3" onClick={copyOrderDetails}>{copiedDetails ? <Check size={14} /> : <Copy size={14} />}{copiedDetails ? "Copied" : "Copy"}</Button> : null}{!editMode ? <Button variant="ghost" className="px-3" onClick={copyTrackingLink}>{copiedTracking ? <Check size={14} /> : <Link2 size={14} />}{copiedTracking ? "Copied" : "Track Link"}</Button> : null}<Button variant="ghost" className="px-3 text-danger hover:text-danger" onClick={deleteOrder} disabled={deletePending || pending}><Trash2 size={14} />{deletePending ? "Deleting..." : "Delete"}</Button><Button variant="ghost" className="px-3" onClick={() => setEditMode((value) => !value)}>{editMode ? "Cancel Edit" : "Edit Details"}</Button>{editMode ? <Button className="px-3" onClick={saveDetails} disabled={pending || deletePending}>{pending ? "Saving..." : "Save Details"}</Button> : null}</div></div>
      {editMode ? <div className="grid gap-3"><Input value={form.customerName} onChange={(e) => setForm((c) => ({ ...c, customerName: e.target.value }))} placeholder="Customer name" /><Input value={form.phoneNumber} onChange={(e) => setForm((c) => ({ ...c, phoneNumber: e.target.value }))} placeholder="Phone number" /><div className="rounded-lg border border-accent/35 bg-accent/[0.06] p-3"><p className="mb-2 text-xs uppercase tracking-[0.18em] text-accent">Maxim Link</p><Input value={form.maximTrackingLink} onChange={(e) => setForm((c) => ({ ...c, maximTrackingLink: e.target.value }))} placeholder="Paste Maxim tracking link here" /></div><div className="overflow-hidden rounded-lg border border-line/80 bg-black/10"><div className="flex items-center justify-between gap-3 border-b border-line/75 px-4 py-3"><div><p className="text-xs uppercase tracking-[0.18em] text-foreground/35">Order Items</p><p className="mt-1 text-xs text-foreground/45">{orderItemSummary.quantity} pcs selected</p></div><p className="text-sm font-semibold">Php {formatPeso(orderItemSummary.subtotal)}</p></div><div className="divide-y divide-line/65">{lineItems.map((item) => { const product = productOptions.find((option) => option.value === item.productName); const available = product ? product.available : true; const quantity = Number(item.quantity || 0); const subtotal = quantity * item.price; return <div key={item.productName} className={cn("grid grid-cols-[minmax(0,1fr)_132px] items-center gap-3 px-4 py-3 transition", quantity > 0 && "bg-accent/[0.06]")}><div className="min-w-0"><p className="truncate text-sm font-semibold">{item.productName}{product && !product.available ? " — SOLD OUT" : ""}</p><p className="mt-0.5 text-xs text-foreground/45">Php {item.price}{quantity > 0 ? ` - Php ${formatPeso(subtotal)}` : ""}</p></div><div className="grid grid-cols-[34px_minmax(48px,1fr)_34px] items-center gap-2"><button type="button" disabled={!available} aria-label={`Decrease ${item.productName}`} onClick={() => stepLineItem(item.productName, -1)} className="flex h-8 w-8 items-center justify-center rounded-md border border-line/70 text-foreground/70 transition hover:border-accent/40 hover:text-foreground disabled:cursor-not-allowed disabled:opacity-35"><Minus size={14} /></button><Input disabled={!available} aria-label={`${item.productName} quantity`} className="h-8 px-2 text-center" type="number" min="0" value={item.quantity} onChange={(e) => updateLineItem(item.productName, e.target.value)} /><button type="button" disabled={!available} aria-label={`Increase ${item.productName}`} onClick={() => stepLineItem(item.productName, 1)} className="flex h-8 w-8 items-center justify-center rounded-md border border-line/70 text-foreground/70 transition hover:border-accent/40 hover:text-foreground disabled:cursor-not-allowed disabled:opacity-35"><Plus size={14} /></button></div></div>; })}</div></div><Select value={form.deliveryMethod} onChange={(value) => setForm((c) => ({ ...c, deliveryMethod: value, deliveryFee: value === "pickup" ? "0" : c.deliveryFee }))} options={deliverySelectOptions} /><Select value={form.paymentMethod} onChange={(value) => setForm((c) => ({ ...c, paymentMethod: value }))} options={paymentSelectOptions} /><div className="space-y-1.5"><p className="text-xs uppercase tracking-[0.16em] text-foreground/35">Delivery Fee (Php)</p><Input type="number" min="0" step="0.01" value={form.deliveryFee} disabled={form.deliveryMethod === "pickup"} onChange={(e) => setForm((c) => ({ ...c, deliveryFee: e.target.value }))} placeholder="0" /><p className="text-[11px] text-foreground/40">{form.deliveryMethod === "pickup" ? "Pickup orders have no delivery fee." : "Applied to the order total."}</p></div><Input type="number" min="0" step="0.01" value={form.discountAmount} onChange={(e) => setForm((c) => ({ ...c, discountAmount: e.target.value }))} placeholder="Discount" /><Input value={form.location} onChange={(e) => setForm((c) => ({ ...c, location: e.target.value }))} placeholder="Area / location" /><Input value={form.address} onChange={(e) => setForm((c) => ({ ...c, address: e.target.value }))} placeholder="Address" /><Input type="datetime-local" value={form.preferredSchedule} onChange={(e) => setForm((c) => ({ ...c, preferredSchedule: e.target.value }))} /><div className="space-y-3 rounded-lg border border-line/75 bg-black/[0.08] p-4"><div><p className="text-xs uppercase tracking-[0.18em] text-foreground/35">Maxim Tracking</p><p className="mt-1 text-xs text-foreground/45">Paste the booking link and rider details after booking Maxim.</p></div><div className="grid gap-3 sm:grid-cols-2"><Input value={form.maximRiderName} onChange={(e) => setForm((c) => ({ ...c, maximRiderName: e.target.value }))} placeholder="Rider name" /><Input value={form.maximRiderPlate} onChange={(e) => setForm((c) => ({ ...c, maximRiderPlate: e.target.value }))} placeholder="Plate / rider ID" /><Input type="datetime-local" value={form.maximScheduledAt} onChange={(e) => setForm((c) => ({ ...c, maximScheduledAt: e.target.value }))} /><Input type="datetime-local" value={form.maximEta} onChange={(e) => setForm((c) => ({ ...c, maximEta: e.target.value }))} /></div><select value={form.maximStatus} onChange={(e) => setForm((c) => ({ ...c, maximStatus: e.target.value }))} className="h-10 w-full rounded-lg border border-line/80 bg-black/10 px-3 text-sm text-foreground outline-none transition hover:border-foreground/18 focus:border-accent/60"><option value="booked">Booked</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select><textarea value={form.maximBookingNotes} onChange={(e) => setForm((c) => ({ ...c, maximBookingNotes: e.target.value }))} placeholder="Maxim booking notes" className="min-h-20 w-full rounded-lg border border-line/80 bg-black/10 px-3.5 py-3 text-sm outline-none transition placeholder:text-foreground/38 hover:border-foreground/18 focus:border-accent/60" /></div><textarea value={form.notes} onChange={(e) => setForm((c) => ({ ...c, notes: e.target.value }))} placeholder="Additional notes" className="min-h-28 w-full rounded-lg border border-line/80 bg-black/10 px-3.5 py-3 text-sm outline-none transition placeholder:text-foreground/38 hover:border-foreground/18 focus:border-accent/60" /><div className="grid gap-3 sm:grid-cols-2"><MiniStat label="Quantity" value={`${orderItemSummary.quantity} pcs`} /><MiniStat label="Total to Pay" value={`Php ${formatPeso(orderItemSummary.total)}`} /></div></div> : <><div className="rounded-lg border border-line/75 bg-black/[0.08] p-4"><DetailBlock label="Customer" value={selectedOrder.customer?.phoneNumber ?? "No phone number"} /><div className="mt-4"><DetailBlock label="Location" value={selectedOrder.address ?? selectedOrder.location ?? "No address provided"} /></div></div><div className="grid grid-cols-2 gap-3"><MiniStat label="Quantity" value={`${selectedOrder.quantity} pcs`} /><MiniStat label="Total to Pay" value={`Php ${String(selectedOrder.totalAmount)}`} /><MiniStat label="Method" value={deliveryMethodLabels[selectedOrder.deliveryMethod] ?? selectedOrder.deliveryMethod} /><MiniStat label="Payment" value={formatPaymentMethod(selectedOrder.paymentMethod)} /><MiniStat label="Schedule" value={formatSchedule(selectedOrder.preferredSchedule)} /></div><div className="rounded-lg border border-line/75 bg-black/[0.08] p-4"><p className="text-xs uppercase tracking-[0.18em] text-foreground/35">Items Ordered</p><OrderItemsList items={getOrderLineItems(selectedOrder)} fallbackQuantity={selectedOrder.quantity} className="mt-3" /></div><div className="grid gap-3 sm:grid-cols-2"><MiniStat label="Item Subtotal" value={`Php ${formatPeso(Math.max(0, Number(selectedOrder.totalAmount ?? 0) - Number(selectedOrder.deliveryFee ?? 0) + Number(selectedOrder.discountAmount ?? 0)))}`} /><MiniStat label="Delivery Fee" value={`Php ${formatPeso(Number(selectedOrder.deliveryFee ?? 0))}`} />{Number(selectedOrder.discountAmount ?? 0) > 0 ? <MiniStat label="Discount" value={`Php ${formatPeso(Number(selectedOrder.discountAmount ?? 0))}`} /> : null}</div>{isMaximOrderView(selectedOrder) ? <div className="space-y-3 rounded-lg border border-line/75 bg-black/[0.08] p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><p className="text-xs uppercase tracking-[0.18em] text-foreground/35">Maxim Tracking</p>{selectedOrder.delivery?.trackingLink ? <a href={selectedOrder.delivery.trackingLink} target="_blank" rel="noreferrer" className="inline-flex h-9 items-center justify-center gap-2 rounded-lg border border-line bg-white/[0.06] px-3 text-sm font-semibold text-foreground transition hover:bg-white/[0.1]"><ExternalLink size={14} />Open Maxim</a> : null}</div><div className="grid gap-3 sm:grid-cols-2"><MiniStat label="Status" value={selectedOrder.delivery?.status ?? "Not booked"} /><MiniStat label="ETA" value={formatSchedule(selectedOrder.delivery?.eta)} /><MiniStat label="Rider" value={formatRider(selectedOrder)} /><MiniStat label="Booking Time" value={formatSchedule(selectedOrder.delivery?.scheduledAt)} /></div>{selectedOrder.delivery?.bookingNotes ? <p className="whitespace-pre-wrap rounded-lg border border-line/70 bg-black/[0.08] px-3 py-2.5 text-sm leading-6 text-foreground/78">{selectedOrder.delivery.bookingNotes}</p> : null}</div> : null}<RiderAssignment order={selectedOrder} onChange={refreshOrders} /><div className="space-y-3 rounded-lg border border-line/75 bg-black/[0.08] p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><p className="text-xs uppercase tracking-[0.18em] text-foreground/35">Notes</p>{getOrderNotes(selectedOrder).length > 0 ? <button type="button" onClick={copyNotes} className="inline-flex items-center gap-2 rounded-md border border-line/70 px-3 py-1 text-xs text-foreground/65 transition hover:border-accent/35 hover:text-foreground">{copiedNotes ? <Check size={13} /> : <Copy size={13} />}{copiedNotes ? "Copied" : "Copy"}</button> : null}</div><div className="space-y-2">{getOrderNotes(selectedOrder).length === 0 ? <p className="rounded-lg border border-dashed border-line/75 px-3 py-3 text-sm text-foreground/45">No notes yet.</p> : null}{getOrderNotes(selectedOrder).map((note) => <div key={note.id} className="rounded-lg border border-line/70 bg-black/[0.08] px-3 py-2.5"><p className="whitespace-pre-wrap text-sm leading-6 text-foreground/82">{note.body}</p><p className="mt-2 text-[11px] text-foreground/38">{formatNoteTime(note.createdAt)}</p></div>)}</div><textarea value={noteDraft} onChange={(e) => setNoteDraft(e.target.value)} placeholder="Add a new note..." className="min-h-24 w-full resize-y rounded-lg border border-line/80 bg-black/10 px-3.5 py-3 text-sm leading-6 text-foreground outline-none transition placeholder:text-foreground/38 hover:border-foreground/18 focus:border-accent/60" /><div className="flex items-center justify-between gap-3"><p className="text-xs text-foreground/42">{noteDraft.trim() ? `${noteDraft.trim().length} characters` : "Write a comment-style note"}</p><Button className="px-3" onClick={addNote} disabled={pending || deletePending || !noteDraft.trim()}>{pending ? "Adding..." : "Add Note"}</Button></div></div></>}</div></div></div> : <div className="flex h-full min-h-[520px] items-center justify-center p-8 text-center text-sm text-foreground/45">{filteredItems.length === 0 ? "No order is selected because the current search returned no results." : "Select an order card to inspect details and update its status."}</div>}</Card></div></div> : null}
    </div>
  );
}

function InfoLine({ icon: Icon, text }: { icon: typeof MapPin; text: string }) { return <div className="flex items-start gap-2"><Icon size={13} className="mt-0.5 shrink-0 text-foreground/30" /><span className="line-clamp-2">{text}</span></div>; }
function OrderItemsList({ items, fallbackQuantity, className }: { items: OrderLineItemView[]; fallbackQuantity?: number; className?: string }) { const displayItems = items.length > 0 ? items : [{ name: "Empanada", quantity: Number(fallbackQuantity ?? 0) }]; return <div className={cn("mt-3 space-y-1.5 rounded-lg border border-line/70 bg-white/[0.03] p-2.5", className)}>{displayItems.map((item) => <div key={`${item.name}-${item.quantity}-${item.price ?? "price"}`} className="flex items-start justify-between gap-3 text-xs"><div className="min-w-0"><p className="truncate font-medium text-foreground/82">{item.name}</p><p className="mt-0.5 text-foreground/42">{item.quantity} pcs{item.price !== undefined ? ` x Php ${item.price}` : ""}</p></div>{item.subtotal !== undefined ? <span className="shrink-0 font-semibold text-foreground/78">Php {item.subtotal}</span> : null}</div>)}</div>; }
function DetailBlock({ label, value }: { label: string; value: string }) { return <div className="space-y-1"><p className="text-xs uppercase tracking-[0.18em] text-foreground/35">{label}</p><p className="text-sm leading-6 text-foreground/78">{value}</p></div>; }
function MiniStat({ label, value }: { label: string; value: string }) { return <div className="rounded-lg border border-line/75 bg-black/[0.08] p-3"><p className="text-xs uppercase tracking-[0.18em] text-foreground/30">{label}</p><p className="mt-2 text-sm font-medium">{value}</p></div>; }

type RiderOption = { id: string; status: string; user: { name: string } };
const riderJobStatusTone: Record<string, string> = { requested: "bg-white/[0.08] text-foreground/70", searching_rider: "bg-amber-500/15 text-amber-200", assigned: "bg-sky-500/15 text-sky-200", accepted: "bg-sky-500/15 text-sky-200", pickup_started: "bg-violet-500/15 text-violet-200", picked_up: "bg-fuchsia-500/15 text-fuchsia-200", delivering: "bg-orange-500/15 text-orange-200", delivered: "bg-emerald-500/15 text-emerald-200", cancelled: "bg-rose-500/15 text-rose-200" };
function RiderAssignment({ order, onChange }: { order: any; onChange: () => Promise<void> | void }) {
  const [riders, setRiders] = useState<RiderOption[] | null>(null); const [selectedRiderId, setSelectedRiderId] = useState(""); const [pending, startTransition] = useTransition(); const [error, setError] = useState<string | null>(null); const activeJob = order?.deliveryJobs?.[0] ?? null;
  useEffect(() => { let cancelled = false; apiFetch<RiderOption[]>("/delivery-network/riders").then((result) => { if (!cancelled) setRiders(result); }).catch(() => { if (!cancelled) setRiders([]); }); return () => { cancelled = true; }; }, []);
  useEffect(() => { setSelectedRiderId(activeJob?.rider?.id ?? ""); }, [activeJob?.rider?.id]);
  const availableRiders = useMemo(() => (riders ?? []).filter((rider) => rider.status === "online" || rider.status === "busy" || rider.id === activeJob?.rider?.id), [riders, activeJob?.rider?.id]);
  function createJob() { setError(null); startTransition(async () => { try { await apiFetch("/delivery-network/jobs/from-order", { method: "POST", body: JSON.stringify({ orderId: order.id, pickupAddress: "Empanada Hauz" }) }); await onChange(); } catch (err) { setError(err instanceof Error ? err.message : "Could not create the delivery job"); } }); }
  function assignRider() { if (!activeJob || !selectedRiderId) return; setError(null); startTransition(async () => { try { await apiFetch(`/delivery-network/jobs/${activeJob.id}/assign`, { method: "PATCH", body: JSON.stringify({ riderId: selectedRiderId }) }); await onChange(); } catch (err) { setError(err instanceof Error ? err.message : "Could not assign the rider"); } }); }
  return <div className="space-y-3 rounded-lg border border-line/75 bg-black/[0.08] p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><p className="text-xs uppercase tracking-[0.18em] text-foreground/35">Rider Assignment</p>{activeJob ? <Badge className={cn("shrink-0 border-0 text-[11px] capitalize", riderJobStatusTone[activeJob.status] ?? riderJobStatusTone.requested)}>{activeJob.status.replaceAll("_", " ")}</Badge> : null}</div>{!activeJob ? <Button className="w-full" onClick={createJob} disabled={pending}>{pending ? "Creating..." : "Create Delivery Job"}</Button> : <><div className="grid gap-3 sm:grid-cols-2"><MiniStat label="Assigned Rider" value={activeJob.rider?.user?.name ?? "Not assigned"} /><MiniStat label="Est. Fare" value={`Php ${String(activeJob.estimatedFare ?? 0)}`} /></div><div className="flex flex-col gap-2 sm:flex-row"><div className="flex-1"><Select value={selectedRiderId} onChange={setSelectedRiderId} options={[{ label: riders === null ? "Loading riders..." : "Select a rider", value: "" }, ...availableRiders.map((rider) => ({ label: `${rider.user.name}${rider.status === "busy" ? " (busy)" : ""}`, value: rider.id }))]} /></div><Button className="sm:w-auto" onClick={assignRider} disabled={pending || !selectedRiderId || selectedRiderId === activeJob.rider?.id}>{pending ? "Assigning..." : activeJob.rider ? "Reassign" : "Assign"}</Button></div>{riders !== null && availableRiders.length === 0 ? <p className="text-xs text-foreground/45">No online riders right now. Add or bring a rider online in Delivery Network.</p> : null}</>}</div>;
}
function CompactStat({ label, value, suffix, accent }: { label: string; value: string; suffix?: string; accent?: boolean }) { return <div className={cn("rounded-lg border px-3 py-2", accent ? "border-accent/25 bg-accent/[0.07]" : "border-line/70 bg-white/[0.03]")}><p className={cn("text-[10px] uppercase tracking-[0.16em]", accent ? "text-accent/70" : "text-foreground/28")}>{label}</p><p className={cn("mt-1 text-sm font-semibold tabular-nums", accent && "text-accent")}>{value}{suffix ? <span className={cn("ml-1 text-xs font-normal", accent ? "text-accent/60" : "text-foreground/45")}>{suffix}</span> : null}</p></div>; }
function toInputDate(value: string) { const date = new Date(value); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}T${String(date.getHours()).padStart(2, "0")}:${String(date.getMinutes()).padStart(2, "0")}`; }
function getLocalDateTimeInputValue() { const now = new Date(); return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}T${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`; }
